INSERT INTO laws (slug, title, category, html, text, download_path, word_count, ref_count, position, updated_at, updated_by) VALUES ('luftverkehrs-ordnung-lvo', 'Luftverkehrs-Ordnung [LVO]', 'Verkehr', '<h2><strong>Luftverkehrs-Ordnung [LuftVO]</strong></h2><ol><li><a href="#_heading=h.7207rqm1ee8k">Grundregeln</a></li><li><a href="#_heading=h.ngdeocfepip0">Benutzung des Luftraums</a></li><li><a href="#_heading=h.r1l8mcrhhrbo">Geschwindigkeit</a></li><li><a href="#_heading=h.xn3ep1v87oi0">Landen</a></li><li><a href="#_heading=h.37vfruri0aqp">Pflichten des Luftverkehrs Teilnehmer</a></li><li><a href="#_heading=h.d3tf8b9t8ck9">Haftung des Luftverkehrs Teilnehmer</a></li><li><a href="#_heading=h.fgzaqho9ar3d">Zeichen und Weisungen der Exekutive</a></li><li><a href="#_heading=h.cywydugavbqa">Flugerlaubnis</a></li><li><a href="#_heading=h.ca5o301qm39c">Gefährliches Flugverhalten</a></li><li><a href="#_heading=h.56b3s8td31ks">Flugverbotszonen</a></li><li><a href="#_heading=h.txst5aryzz3j">Fallschirmspringen</a></li><li><a href="#_heading=h.lev945gfwoz">Entzug der Flugerlaubnis</a></li></ol><p>Jeder Abschnitt kann nur einmal bestraft werden!</p><h3><strong>Strafe</strong></h3><p>Die Strafen für dieses Gesetz sind im Bußgeldkatalog definiert.</p><h2>§ 1 Grundregeln</h2><p>(1) Die Teilnahme am Luftverkehr erfordert ständige Vorsicht und gegenseitige Rücksicht.</p><p>(2) Wer am Luftverkehr teilnimmt hat sich so zu verhalten, dass kein Anderer geschädigt, gefährdet oder mehr, als nach den Umständen unvermeidbar, behindert oder belästigt wird.</p><p>(3) Ein Luftfahrzeug ist jedes Gerät, welches bemannt oder unbemannt in der Lage ist aus eigener Kraft den Boden zu verlassen und diesen Zustand aus eigener Kraft aufrecht zu erhalten.</p><p>(4) Ein Luft Verkehrsteilnehmer ist eine Person, welche ein Luftfahrzeug kontrolliert, welches sich nicht abgeschaltet am Boden befindet.</p><h2>§ 2 Benutzung des Luftraums</h2><p>(1) Luftfahrzeuge müssen zu jederzeit die Mindestflughöhe einhalten. </p><ol><li>Diese beträgt innerhalb der Stadtgrenzen 300 Fuß (91 Meter).</li><li>Außerhalb der Stadtgrenzen beträgt diese 100 Fuß (30 Meter).</li></ol><p>(2) Es ist jederzeit ein Sicherheitsabstand von 100 m zu anderen Luftverkehrs Teilnehmern einzuhalten.</p><p>(3) Ausnahmen für (1) und (2) gelten für </p><ol><li>Die Exekutive, das Medic Department während eines Einsatzes.</li><li>Den Start- und Landevorgang..</li></ol><h2>§ 3 Geschwindigkeit</h2><p>(1) Die zulässige Höchstgeschwindigkeit ist nicht beschränkt, ist vom Piloten aber den Wetter- und Sichtverhältnissen anzupassen.</p><h2>§ 4 Landen</h2><p>(1) Das Landen ist nur zulässig</p><ol><li>auf gekennzeichneten öffentlichen Landeplätzen.</li><li>auf öffentlichen Flächen mit ausreichendem Platz, sofern diese nicht für den Straßenverkehr vorgesehen sind und sich zum Zeitpunkt der Landung keine Menschenmengen vor Ort befinden.</li><li>Auf privatem Gelände, sofern das Einverständnis des Besitzers vorliegt.</li><li>Auf privaten Landeplätzen, sofern das Einverständnis des Besitzers vorliegt.</li><li>sofern keine Personen oder Gegenstände gefährdet werden.</li></ol><p>(2) Die Exekutive, das Medic Department dürfen während eines aktiven Einsatzes nach eigenem Ermessen unter Abwägung der Gefahren an jeder Stelle Landen, sind dabei aber für Schäden haftbar.</p><h2>§ 5 Pflichten des Luftverkehrs Teilnehmer </h2><p>(1) Der Luftverkehrs Teilnehmer darf unter keinem Einfluss durch:</p><ol><li>Betäubungsmittel,</li><li>Alkoholeinfluss oder</li><li>Rauschgiftmittel stehen.</li></ol><h2>§ 6 Haftung des Luftverkehrs Teilnehmer</h2><p>(1) Der Luftverkehrs-Teilnehmer haftet eigenständig für die Güter, die er im Luftfahrzeug bei sich führt.</p><p>(1.1) Ausgenommen die Unschuld des Luftverkehrs Teilnehmers kann ausreichend nachgewiesen werden.</p><p>(1.2) Die Haftung für die Güter im Luftfahrzeug kann mittels eines schriftlichen Vertrags vor Beginn des Fluges abgegeben werden, sofern der Luftverkehrs Teilnehmer sowie der Haftende diesen unterzeichnet haben.</p><p>(2) Der Luftverkehrs-Teilnehmer haftet für den ordentlichen Zustand seines Luftfahrzeugs. </p><h2>§ 7 Zeichen und Weisungen der Exekutive</h2><p>(1) Die Zeichen und Weisungen der Exekutive sind zu befolgen. Sie gehen allen anderen Anordnungen und sonstigen Regeln vor, entbinden den Luftverkehrs Teilnehmer jedoch nicht von seiner Sorgfaltspflicht.</p><h2>§ </h2><h2>8 Flugerlaubnis </h2><ol><li>Jeder Beteiligte des Luftverkehrs ist dazu verpflichtet, eine gültige Fluglizenz bei sich zu führen und diese nach Aufforderung der Exekutive vorzuweisen. </li><li>Sollten die Grundvoraussetzungen der Fluglizenz und die Grundkenntnisse der LVO missachtet werden, wird das Vergehen mit einer Entziehung der Lizenz belangt. <br /></li></ol><h2>§ 9 Gefährliches Flugverhalten</h2><ol><li>Wer den Luftverkehr durch Zerstörung von Objekten und rücksichtsloses Fliegen, sowie durch Bereitung von Hindernissen beeinträchtigt oder eine ähnlich gefährliche Handlung im Luftverkehr ausübt.</li></ol><h2>§ 10 Flugverbotszonen</h2><ol><li>Die Exekutive kann jederzeit Flugverbotszonen ausrufen, diese gelten bis zur Aufhebung durch die Exekutive. Die Exekutive kann dauerhaft Flugverbotszonen ausrufen.</li><li>Ausgerufene Sperrzonen sind automatisch Flugverbotszonen</li><li>Das be- und überfliegen von Flugverbotszonen, sowie das Starten und Landen innerhalb dieser ist nicht gestattet, sofern es nicht explizit durch die Exekutive genehmigt wurde.</li><li>Luftfahrzeuge der Exekutive, sowie des Medic Deparment sind von (3) ausgenommen.</li><li>Zur Gefahrenabwendung kann es bei Verstößen gegen diesen Paragraphen zu Beschuss durch die Exekutive kommen.</li></ol><h2>§ 11 Fallschirmspringen</h2><ol><li>Flugverbotszonen gelten auch für Fallschirmspringer.</li><li>Die Mindestflughöhe gilt nicht für Fallschirmspringer</li><li>Ein Fallschirmspringer darf zu keiner Zeit Personen außer sich selbst oder Gegenstände gefährden.</li><li>Die Landeflächen gelten wie in §5 auch für Fallschirmspringer.</li><li>Die Exekutive und der Medic Department sind während eines aktiven Einsatzes von diesem Paragraphen ausgeschlossen</li></ol><h2>§ 12 Entzug der Flugerlaubnis</h2><ol><li>Entspricht die körperliche oder geistige Verfassung des Piloten zum Zeitpunkt einer polizeilichen Kontrolle nicht dem erforderlichen Maß, so kann ihm der Weiterflug untersagt werden und die Flugerlaubnis vorläufig entzogen werden.</li></ol><p>Kriterien für eine nicht ausreichende körperliche oder geistige Verfassung ist:</p><ul><li><ol><li>Rückstände von Alkohol, Betäubungsmitteln oder anderer berauschender Mittel                       im Blut,</li><li>Körperliche Beeinträchtigungen,</li><li>Unerlaubtes Entfernen vom Unfallort, sofern dem Piloten ersichtlich ist, dass Menschen verletzt wurden oder ein bedeutender Schaden an fremden Eigentum entstanden ist.</li><li>Gefährliches Flugverhalten,</li><li>ab der zweiten Verletzung der Mindestflughöhe</li></ol></li></ul><ol><li>Die Flugelaubnis kann für bis zu 24 Stunden durch einen Exekutivbeamten entzogen werden, dieser Zeitraum kann auf 7 Tage durch einen Richter verlängert werden.</li><li>Über den endgültigen Entzug der Flugerlaubnis entscheidet ein Gerichtsverfahren.</li></ol><p><em>Sollte ein Paragraph rechtliche Fehler aufweisen, so ist dieser so lange außer Kraft gesetzt, bis dieser von der Regierung neu verabschiedet wurde. </em></p><p><em>Dieses Gesetz wurde im Goverment über eine Mehrheitsabstimmung verabschiedet und ist somit gültig.</em></p>', 'Luftverkehrs-Ordnung [LuftVO]


Grundregeln

